@layer components {
  /* Notifications list
  /* ------------------------------------------------------------------------ */

  .notifications-list {
    --panel-size: 45ch;

    .tray__item {
      position: relative;

      &[aria-selected] {
        outline: 0;

        .card {
          border-radius: 0.25ch;
          outline: var(--focus-ring-size) solid var(--focus-ring-color);
          outline-offset: var(--focus-ring-offset);
        }
      }
    }

    .card {
      @media (prefers-color-scheme: dark) {
        box-shadow: 0 0 0 1px var(--color-ink-lighter);
      }
    }

    .card__header {
      column-gap: var(--inline-space-half);
    }

    &:has(.card--notification) {
      .notifications-list__blank-slate {
        display: none;
      }
    }
  }

  /* Read items
  /* ------------------------------------------------------------------------ */

  .notifications-list--read {
    &:not(:has(.card--notification)) {
      display: none;
    }

    .card {
      box-shadow: 0 0 0 1px var(--color-ink-lighter);
    }

    .card__notification-unread-indicator {
      --btn-background: transparent;
      --btn-size: 1.8em;

      margin: 2px;

      .icon {
        block-size: 1.7em;
        color: var(--color-ink);
        inline-size: 1.7em;
        opacity: 1;
      }
    }
  }


 /* Help
 /* ------------------------------------------------------------------------ */
  .notifications-help {
    h3 {
      font-size: var(--text-medium);
      margin: 0;
    }

    .icon {
      --icon-size: 1.2em;

      vertical-align: text-top;
    }

    ol {
      margin-block: var(--block-space-half) var(--block-space);

      &:last-of-type {
        margin-block-end: var(--block-space-half);
      }
    }
  }

  .notifications-help__explainer {
    padding: var(--block-space);
  }

  .notifications__on-message {
    display: none;

    .notifications--on & {
      display: revert;
    }
  }

  .notifications__off-message {
    display: revert;

    .notifications--on & {
      display: none;
    }
  }

  .notifications__status {
    --panel-border-radius: 0.5em;
    --panel-padding: var(--block-space);
  }
}

==== saas native_devices
<div class="native-devices margin-block-start">
  <h3 class="txt-small txt-uppercase divider">Mobile Devices</h3>

  <% if Current.identity.devices.any? %>
    <p class="txt-small">
      You have <%= pluralize(Current.identity.devices.count, "mobile device") %> registered for push notifications.
    </p>
    <%= link_to "Manage devices", saas.my_devices_path, class: "btn txt-small" %>
  <% else %>
    <p class="txt-small color-secondary">
      No mobile devices registered. Install the iOS or Android app to receive push notifications on your phone.
    </p>
  <% end %>
</div>
==== saas my devices
<% @page_title = "Registered devices" %>

<section class="panel panel--centered flex flex-column gap" style="--panel-size: auto;">
  <% if @devices.any? %>
    <h1 class="txt-x-large font-weight-black txt-tight-lines margin-none">
      Registered devices
    </h1>
    <ul class="flex flex-column gap list-style-none full-width pad border-radius border" style="--inline-space: var(--block-space);">
      <% @devices.each do |device| %>
        <li class="flex align-center gap txt-medium txt-align-start">
          <div class="flex-1 flex flex-column">
            <span>
              <strong><%= device.name || "Unnamed device" %></strong>
              (<%= device.platform == "apple" ? "iOS" : "Android" %>)
            </span>
            <span class="txt-subtle txt-x-small">
              Added <%= local_datetime_tag(device.created_at, style: :daysago) %>
            </span>
          </div>
          <%= button_to saas.my_device_path(device), method: :delete, class: "btn btn--circle-mobile txt-small", data: { confirm: "Remove this device?" }, form: { class: "flex-item-no-shrink" } do %>
            <%= icon_tag "trash", class: "icon--mobile-only" %>
            <span class="overflow-ellipsis">Remove</span>
          <% end %>
        </li>
      <% end %>
    </ul>
  <% else %>
    <h1 class="txt-x-large font-weight-black margin-none">No devices registered</h1>
    <p class="margin-none-block-start">Mobile devices registered with the mobile app will receive push notifications and will be listed here.</p>
  <% end %>

  <%= link_to session_menu_path(script_name: nil), class: "btn center txt-small margin-block-start hide-on-native", data: { turbo_prefetch: false } do %>
    <span>Your Fizzy accounts</span>
  <% end %>
</section>
"
}

