arguments.command:
cd /app && cat > /tmp/edit_sw.rb <<'EOF'
path = "app/views/pwa/service_worker.js.erb"
s = File.read(path)
anchor = "TurboOffline.start()"
raise "anchor" unless s.scan(anchor).size == 1
handlers = <<-JS
self.addEventListener("push", (event) => {
  const { title = "Fizzy", body, url, tag } = event.data?.json() ?? {}

  event.waitUntil(self.registration.showNotification(title, {
    body,
    tag,
    renotify: Boolean(tag),
    icon: "/app-icon-192.png",
    data: { url }
  }))
})

self.addEventListener("notificationclick", (event) => {
  event.notification.close()
  event.waitUntil(openNotificationUrl(event.notification.data?.url ?? "/"))
})

async function openNotificationUrl(url) {
  const clients = await self.clients.matchAll({ type: "window", includeUncontrolled: true })
  const client = clients.find((client) => client.url.startsWith(self.location.origin))

  if (client?.navigate) {
    await client.focus()
    return client.navigate(url)
  } else {
    return self.clients.openWindow(url)
  }
}

JS
s = s.sub(anchor) { handlers + anchor }
File.write(path, s)
puts "ok"
EOF
